#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *data = NULL;
    size_t count = 0, capacity = 0;
    int x;
    while (scanf("%d", &x) == 1) {
        if (count == capacity) {
            size_t new_capacity = capacity ? capacity * 2 : 4;
            int *bigger = realloc(data, new_capacity * sizeof *data);
            if (bigger == NULL) {
                free(data);
                return 1;
            }
            data = bigger;
            capacity = new_capacity;
        }
        data[count++] = x;
    }
    printf("%zu\n", count);
    for (size_t i = count; i > 0; i--) {
        printf(i > 1 ? "%d " : "%d\n", data[i - 1]);
    }
    free(data);
    return 0;
}

