#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t length = 0, capacity = 4;
    char *line = malloc(capacity);
    if (line == NULL) {
        return 1;
    }
    int c;
    while ((c = getchar()) != EOF && c != '\n') {
        if (length + 1 == capacity) {
            capacity *= 2;
            char *bigger = realloc(line, capacity);
            if (bigger == NULL) {
                free(line);
                return 1;
            }
            line = bigger;
        }
        line[length++] = (char)c;
    }
    line[length] = '\0';
    printf("%zu\n", length);
    for (size_t i = length; i > 0; i--) {
        putchar(line[i - 1]);
    }
    putchar('\n');
    free(line);
    return 0;
}

