int main(void) {
    int *a = NULL;
    size_t cap = 0;
    for (int i = 1; i <= 5; i++) {
        if ((size_t)i > cap) {
            cap = cap ? cap * 2 : 1;
            int *t = realloc(a, cap * sizeof *a);
            if (t == NULL) {
                free(a);
                return 1;
            }
            a = t;
        }
        a[i - 1] = i * i;
    }
    printf("%zu %d\n", cap, a[4]);
    free(a);
    return 0;
}
